<template><div class="chat-dock-root"><ChatLauncher :count="windows.length" @open="newWindow"/><div class="chat-dock-windows"><ChatWindow v-for="w in visibleWindows" :key="w.id" :window-id="w.id" :conversation-id="w.conversationId" :minimized="w.minimized" :role="role" @close="close(w.id)" @minimize="minimize(w.id)" @created="setConversation(w.id,$event)" @focus="activeId=w.id"/></div></div></template>
<script setup lang="ts">import{computed,ref,onMounted,onBeforeUnmount}from'vue';import{useStore}from'vuex';import ChatWindow from'./ChatWindow.vue';import ChatLauncher from'./ChatLauncher.vue';const store=useStore(),role=computed(()=>store.getters['auth/user']?.role||'User');type WindowState={id:string;conversationId:string|null;minimized:boolean};const windows=ref<WindowState[]>([]),activeId=ref<string|null>(null),isMobile=ref(false);const visibleWindows=computed(()=>isMobile.value?windows.value.filter(w=>w.id===activeId.value):windows.value);function updateViewport(){isMobile.value=window.innerWidth<=560}onMounted(()=>{updateViewport();window.addEventListener('resize',updateViewport)});onBeforeUnmount(()=>window.removeEventListener('resize',updateViewport));function newWindow(){const max=3;if(windows.value.length>=max){const minimized=windows.value.find(w=>w.minimized);if(minimized){minimized.minimized=false;activeId.value=minimized.id}else activeId.value=windows.value[windows.value.length-1]?.id||null;return}const id=crypto.randomUUID();windows.value.push({id,conversationId:null,minimized:false});activeId.value=id}function close(id:string){windows.value=windows.value.filter(w=>w.id!==id);if(activeId.value===id)activeId.value=windows.value[windows.value.length-1]?.id||null}function minimize(id:string){const row=windows.value.find(w=>w.id===id);if(row)row.minimized=!row.minimized;if(row&&!row.minimized)activeId.value=id}function setConversation(id:string,conversationId:string){const row=windows.value.find(w=>w.id===id);if(!row)return;const duplicate=windows.value.find(w=>w.id!==id&&w.conversationId===conversationId);if(duplicate){duplicate.minimized=false;close(id);activeId.value=duplicate.id;return}row.conversationId=conversationId;activeId.value=id}defineExpose({newWindow});</script>
